SELECT CASE WHEN orders.status IN ('CANCELLED', 'PENDING') THEN 'priority' ELSE 'other' END AS status_group, ROUND(AVG(order_items.unit_price), 2) AS avg_unit_price FROM order_items LEFT JOIN orders ON order_items.order_id = orders.id WHERE orders.discount >= 0.29 GROUP BY CASE WHEN orders.status IN ('CANCELLED', 'PENDING') THEN 'priority' ELSE 'other' END ORDER BY avg_unit_price DESC;
